export function createHeroControls(hero,recipe,onChange,options={}){
  const storageKey=options.storageKey||'alpic-landing-studio-v2',idPrefix=options.idPrefix||'hero';
  const defaults={graph:{...structuredClone(recipe),lineColor:'#000000',squareColor:'#000000',lineOpacity:100,squareOpacity:100,stroke:1.1,squareStroke:.6},imageOffsetX:0,imageOffsetY:0,imageScale:100,imageWidth:100,imageHeight:100,imageRotation:0,followImage:true,graphScale:100,graphRotation:0,dashLength:6,dashGap:6,fitToMountain:true,scaleX:100,scaleY:100,offsetX:0,offsetY:0,pixelSize:6,mixed:false,levels:3,brightness:100,contrast:1,saturation:100,backgroundOpacity:10,imageMotion:35,plate:'SQUARES',texture:false,traces:false};
  if(options.graphOnly){Object.assign(defaults.graph,options.graphDefaults);defaults.opacity=options.opacity??14}
  if(options.pixels)Object.assign(defaults,{pixelSize:8,mixed:true,density:32,opacity:options.opacity??14});
  const settingsId=options.settingsId||(options.graphOnly?'background':'mountain');
  let state=structuredClone(defaults),undo=[],redo=[],editKey=null;
  const applyStored=(previous,legacy)=>{if(!previous)return;Object.assign(state,previous);state.graph={...defaults.graph,...previous.graph,preset:options.graphOnly?(previous.graph?.preset??defaults.graph.preset):20};if(legacy)Object.assign(state,{fitToMountain:true,scaleX:100,scaleY:100,offsetX:0,offsetY:0})};
  let local=null,localAt=0,legacy=false;
  try{const raw=JSON.parse(localStorage.getItem(storageKey));if(raw?.state){local=raw.state;localAt=Date.parse(raw.savedAt)||0}else if(raw)local=raw;else if(!options.graphOnly){const v1=JSON.parse(localStorage.getItem('alpic-landing-studio-v1'));if(v1){local=v1;legacy=true}}}catch{}
  const publishedAt=Date.parse(options.published?.savedAt)||0;
  if(options.published?.state&&publishedAt>=localAt)applyStored(options.published.state);else applyStored(local,legacy);
  const customize=document.createElement('button');customize.className='mountain-config-trigger';customize.type='button';customize.textContent='⚙ Configure';customize.setAttribute('aria-label','Configure mountain');customize.setAttribute('aria-haspopup','dialog');customize.setAttribute('aria-expanded','false');customize.setAttribute('aria-controls',idPrefix+'-mountain-config-menu');hero.append(customize);
  const popup=document.createElement('div');popup.id=idPrefix+'-mountain-config-menu';popup.className='mountain-config-popup';popup.setAttribute('popover','auto');popup.setAttribute('role','dialog');popup.setAttribute('aria-label','Mountain configuration');document.body.append(popup);
  const panel=document.createElement('section');panel.className='hero-controls';popup.append(panel);
  panel.innerHTML='<div class="hero-controls-heading"><div><span class="studio-kicker">21 / GRAND ALPINE</span><strong>Mountain configuration</strong></div><button type="button" class="studio-close" aria-label="Close mountain configuration">×</button></div><div class="popup-motion"><button type="button" class="studio-pause"></button><button type="button" class="studio-reset">Reset ↺</button></div><div class="hero-control-tabs" role="tablist" aria-label="Mountain settings categories"></div><div class="hero-controls-body"></div><div class="hero-controls-footer"><div class="studio-history"><button type="button" class="studio-undo" disabled>↶ Undo</button><button type="button" class="studio-redo" disabled>Redo ↷</button></div><button type="button" class="studio-export">Save settings ↓</button><span>Save applies everywhere this page is opened</span></div>';
  if(options.graphOnly){customize.textContent='⚙ Background';customize.setAttribute('aria-label','Configure background mountain');popup.classList.add('backdrop-config-popup');popup.setAttribute('aria-label','Background mountain configuration');panel.querySelector('strong').textContent='Background mountain';panel.querySelector('.studio-kicker').textContent='FRACTURE / BACKGROUND';}
  const range=(key,label,min,max,step=1,suffix='%')=>`<label class="hero-setting"><span>${label}<output data-output="${key}"></output></span><input data-setting="${key}" aria-label="${label}" type="range" min="${min}" max="${max}" step="${step}" data-suffix="${suffix}"></label>`;
  const color=(key,label)=>`<label class="hero-color"><span>${label}</span><input type="color" data-setting="${key}" aria-label="${label}"></label>`;
  const select=(key,label,options)=>`<label class="hero-select"><span>${label}</span><select data-setting="${key}" aria-label="${label}">${options.map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></label>`;
  const panels={
    Position:`<h3 class="position-group">Mountain image</h3>${range('imageOffsetX','Mountain horizontal position',-40,40)}${range('imageOffsetY','Mountain vertical position',-40,40)}${range('imageScale','Mountain scale',25,180)}${range('imageWidth','Mountain width scale',50,150)}${range('imageHeight','Mountain height scale',50,150)}${range('imageRotation','Mountain rotation',-30,30,.5,'°')}<h3 class="position-group">Graph overlay</h3><label class="hero-fit-toggle"><input type="checkbox" data-setting="followImage" aria-label="Move graph with mountain image">Move graph with mountain image</label><label class="hero-fit-toggle"><input type="checkbox" data-setting="fitToMountain" aria-label="Fit graph to mountain silhouette">Fit graph to mountain silhouette</label>${range('offsetX','Graph horizontal position',-40,40)}${range('offsetY','Graph vertical position',-40,40)}${range('graphScale','Graph scale',25,180)}${range('scaleX','Graph width scale',25,150)}${range('scaleY','Graph height scale',25,150)}${range('graphRotation','Graph rotation',-45,45,.5,'°')}<button type="button" class="studio-align-reset">Reset positions & scales ↺</button>`,
    Shape:`<p>The original Grand Alpine geometry, with the prototype’s controls.</p>${range('graph.height','Peak height',25,100)}${range('graph.width','Mountain width',30,100)}${range('graph.density','Point density',10,100)}${range('graph.detail','Connections',0,100)}${range('graph.irregularity','Irregularity',0,100)}<div class="hero-graph-count"></div>`,
    Lines:`<p>Black lines sit over the mountain. Tune their weight and visibility.</p>${color('graph.lineColor','Line color')}${range('graph.stroke','Line weight',.1,6,.1,' px')}${range('graph.lineOpacity','Line opacity',0,100)}${range('graph.interiorOpacity','Interior line opacity',0,100)}${select('graph.lineStyle','Line style',[['solid','Solid'],['dashed','Dashed'],['dotted','Dotted']])}`,
    Squares:`${color('graph.squareColor','Square color')}${range('graph.dot','Square size',0,30,.1,' px')}${range('graph.squareStroke','Square border weight',.25,4,.05,' px')}${range('graph.squareOpacity','Square opacity',0,100)}${select('graph.nodeStyle','Square style',[['solid','Filled'],['outline','Hollow'],['mixed','Mixed']])}${range('graph.highlight','Highlighted squares',0,100)}${color('graph.highlightColor','Highlight color')}`,
    Motion:`<p>Pause Motion here freezes both layers. Control their movement below.</p>${select('graph.motionStyle','Graph movement',[['drift','Drift'],['breathe','Breathe'],['wave','Wave'],['dash-shuffle','Dash Shuffle']])}<div class="drift-arrangement"><button type="button" class="studio-arrange">New arrangement ↻</button></div>${range('graph.speed','Motion speed',.1,3,.1,'×')}${range('graph.amplitude','Graph motion amount',0,100)}${range('imageMotion','Mountain motion amount',0,100)}<div class="dash-shuffle-settings"><p>Dashes continuously shuffle along the existing connections. Motion speed and Graph motion amount control their rhythm.</p>${range('dashLength','Shuffle dash length',1,24,.5,' px')}${range('dashGap','Shuffle gap length',1,24,.5,' px')}</div>`,
    Image:`<p>The mountain breaks into pixels. Silver photograph is the same peak in near-monochrome, and mixed sizes lets large and small pixels share one frame.</p>${select('plate','Study',[['SQUARES','Colour squares'],['SILVER','Silver photograph'],['EVEREST','Everest'],['DITHER','Dither'],['PHOTO','Photo'],['IRIDESCENT','Iridescent'],['SCANLINE','Scanline'],['LINES','Lines'],['BLOCKS','Blocks'],['PIXELS','Pixels'],['GLITCH','Glitch'],['ANAGLYPH','Anaglyph'],['LIVE','Live']])}<label class="hero-fit-toggle"><input type="checkbox" data-setting="traces" aria-label="Traces on the mountain">Traces</label>${range('pixelSize','Pixel size',1,12,.5,' px')}<label class="hero-fit-toggle"><input type="checkbox" data-setting="mixed" aria-label="Mixed pixel sizes">Mixed pixel sizes</label>${range('levels','Color levels',2,8,1,'')}${range('brightness','Image brightness',0,200)}${range('contrast','Image contrast',.5,2,.05,'×')}${range('saturation','Image saturation',0,200)}<label class="hero-fit-toggle"><input type="checkbox" data-setting="texture" aria-label="Image texture">Image texture</label><div class="texture-settings">${range('backgroundOpacity','Background image opacity',0,30)}</div>`
  };
  if(options.pixels){
    for(const name of Object.keys(panels))delete panels[name];
    panels.Pixels=`<p>Alpine Raster, study 49, sits behind the words.</p>${range('opacity','Opacity',4,40)}`;
  }
  if(options.graphOnly&&!options.pixels){
    panels.Position=range('opacity','Background opacity',1,40)+range('offsetX','Graph horizontal position',-50,50)+range('offsetY','Graph vertical position',-50,50)+range('graphScale','Graph scale',25,180)+range('scaleX','Graph width scale',25,150)+range('scaleY','Graph height scale',25,150)+range('graphRotation','Graph rotation',-45,45,.5,'°')+'<button type="button" class="studio-align-reset">Reset positions & scales ↺</button>';
    panels.Shape=select('graph.preset','Mountain preset',window.Mountain.presets.map((p,i)=>[i,(i+1)+' / '+p.short]))+panels.Shape.replace('<p>The original Grand Alpine geometry, with the prototype’s controls.</p>','')+range('graph.yaw','3D yaw',-180,180,1,'°')+range('graph.pitch','3D pitch',-80,80,1,'°')+range('graph.depth','3D depth',25,180);
    panels.Motion='<p>Animate the background independently from the hero mountain.</p>'+select('graph.motionStyle','Graph movement',[['drift','Drift'],['breathe','Breathe'],['wave','Wave'],['dash-shuffle','Dash Shuffle']])+'<div class="drift-arrangement"><button type="button" class="studio-arrange">New arrangement ↻</button></div>'+range('graph.speed','Motion speed',.1,3,.1,'×')+range('graph.amplitude','Graph motion amount',0,100)+'<div class="dash-shuffle-settings">'+range('dashLength','Shuffle dash length',1,24,1,' px')+range('dashGap','Shuffle gap length',1,24,1,' px')+'</div>';
    delete panels.Image;
  }
  if(!options.graphOnly&&!options.pixels){panels.Position=panels.Position.replace(/<h3 class="position-group">Graph overlay<\/h3>[\s\S]*?(<button type="button" class="studio-align-reset">)/,'$1');for(const name of ['Shape','Lines','Squares','Motion'])delete panels[name]}
  const tabs=panel.querySelector('.hero-control-tabs'),body=panel.querySelector('.hero-controls-body'),firstTab=Object.keys(panels)[0];
  for(const [name,markup] of Object.entries(panels)){const tab=document.createElement('button');tab.type='button';tab.textContent=name;tab.setAttribute('role','tab');tab.setAttribute('aria-selected',String(name===firstTab));tab.id=idPrefix+'-tab-'+name;tab.setAttribute('aria-controls',idPrefix+'-panel-'+name);tabs.append(tab);const content=document.createElement('div');content.className='hero-control-panel';content.id=idPrefix+'-panel-'+name;content.setAttribute('role','tabpanel');content.setAttribute('aria-labelledby',tab.id);content.hidden=name!==firstTab;content.innerHTML=markup;body.append(content);tab.addEventListener('click',()=>{for(const b of tabs.children)b.setAttribute('aria-selected',String(b===tab));for(const p of body.children)p.hidden=p!==content;body.scrollTop=0})}
  const get=key=>key.startsWith('graph.')?state.graph[key.slice(6)]:state[key];
  const set=(key,value)=>{if(key.startsWith('graph.'))state.graph[key.slice(6)]=value;else state[key]=value};
  function sync(){if(options.graphOnly){const pause=panel.querySelector('.studio-pause');pause.textContent=state.graph.motion?'Ⅱ Pause Motion':'▷ Play Motion';pause.setAttribute('aria-label',state.graph.motion?'Pause background animation':'Play background animation');pause.setAttribute('aria-pressed',String(state.graph.motion));panel.querySelector('.studio-kicker').textContent=options.pixels?'PIXEL FIELD':(Number(state.graph.preset)+1)+' / '+window.Mountain.presets[state.graph.preset].short.toUpperCase()}const shuffle=panel.querySelector('.dash-shuffle-settings'),drift=panel.querySelector('.drift-arrangement');if(shuffle)shuffle.hidden=state.graph.motionStyle!=='dash-shuffle';if(drift)drift.hidden=state.graph.motionStyle!=='drift';const textureSettings=panel.querySelector('.texture-settings');if(textureSettings)textureSettings.hidden=!state.texture;for(const input of panel.querySelectorAll('[data-setting]')){if(input.type==='checkbox')input.checked=!!get(input.dataset.setting);else input.value=get(input.dataset.setting);const output=panel.querySelector(`[data-output="${input.dataset.setting}"]`);if(output)output.textContent=Number(Number(input.value).toFixed(2))+(input.dataset.suffix||'')}}
  function history(){panel.querySelector('.studio-undo').disabled=!undo.length;panel.querySelector('.studio-redo').disabled=!redo.length}
  function checkpoint(){undo.push(structuredClone(state));if(undo.length>40)undo.shift();redo=[];history()}
  function emit(){try{localStorage.setItem(storageKey,JSON.stringify(state))}catch{}onChange(state);history()}
  for(const input of panel.querySelectorAll('[data-setting]')){input.addEventListener('input',()=>{if(editKey!==input.dataset.setting){checkpoint();editKey=input.dataset.setting}if(options.graphOnly&&input.dataset.setting==='graph.preset'){state.graph={...window.Mountain.defaults(Number(input.value)),lineColor:state.graph.lineColor,squareColor:state.graph.squareColor,stroke:state.graph.stroke,squareStroke:state.graph.squareStroke,lineOpacity:state.graph.lineOpacity,squareOpacity:state.graph.squareOpacity,motion:state.graph.motion,speed:state.graph.speed,amplitude:state.graph.amplitude}}set(input.dataset.setting,input.type==='checkbox'?input.checked:input.type==='range'?Number(input.value):input.value);sync();emit()});input.addEventListener('change',()=>editKey=null);input.addEventListener('blur',()=>editKey=null)}
  panel.querySelector('.studio-arrange')?.addEventListener('click',()=>{checkpoint();state.graph.seed=Math.floor(Math.random()*1e6);state.graph.offsets={};emit()});
  panel.querySelector('.studio-align-reset')?.addEventListener('click',()=>{checkpoint();for(const key of ['imageOffsetX','imageOffsetY','imageScale','imageWidth','imageHeight','imageRotation','followImage','graphScale','graphRotation','scaleX','scaleY','offsetX','offsetY','fitToMountain'])state[key]=defaults[key];sync();emit()});
  panel.querySelector('.studio-reset').addEventListener('click',()=>{checkpoint();state=structuredClone(defaults);sync();emit()});
  panel.querySelector('.studio-undo').addEventListener('click',()=>{if(!undo.length)return;redo.push(structuredClone(state));state=undo.pop();editKey=null;sync();emit()});
  panel.querySelector('.studio-redo').addEventListener('click',()=>{if(!redo.length)return;undo.push(structuredClone(state));state=redo.pop();editKey=null;sync();emit()});
  const saveStatus=panel.querySelector('.hero-controls-footer>span');
  panel.querySelector('.studio-export').addEventListener('click',async()=>{const button=panel.querySelector('.studio-export');button.disabled=true;saveStatus.textContent='Saving…';try{const response=await fetch('/studio-settings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:settingsId,state})});if(!response.ok)throw new Error();const saved=await response.json();try{localStorage.setItem(storageKey,JSON.stringify({savedAt:saved.savedAt,state}))}catch{}saveStatus.textContent='Saved. This is what every browser will show.'}catch{saveStatus.textContent='Could not save. The preview server has to be running.'}button.disabled=false});
  function positionDropup(){const r=customize.getBoundingClientRect(),width=Math.min(380,innerWidth-24),height=Math.max(140,Math.min(560,r.top-24));popup.style.width=width+'px';popup.style.left=Math.max(12,Math.min(r.right-width,innerWidth-width-12))+'px';popup.style.bottom=(innerHeight-r.top+10)+'px';popup.style.setProperty('--dropup-height',height+'px')}
  customize.addEventListener('click',()=>{positionDropup();popup.togglePopover()});panel.querySelector('.studio-close').addEventListener('click',()=>popup.hidePopover());popup.addEventListener('toggle',event=>customize.setAttribute('aria-expanded',String(event.newState==='open')));
  for(const event of ['resize','scroll'])window.addEventListener(event,()=>{if(popup.matches(':popover-open'))positionDropup()},{passive:true});
  const configHash=options.graphOnly?'#configure-background':'#configure-mountain';
  function openFromHash(){if(location.hash!==configHash)return;hero.scrollIntoView({block:'center'});positionDropup();if(!popup.matches(':popover-open'))popup.showPopover()}
  window.addEventListener('hashchange',openFromHash);
  if(performance.getEntriesByType('navigation')[0]?.type!=='reload')openFromHash();


  if(options.graphOnly)panel.querySelector('.studio-pause').addEventListener('click',()=>{checkpoint();state.graph.motion=!state.graph.motion;sync();emit()});
  function setTexture(value){const next=!!value;if(!!state.texture===next)return;checkpoint();state.texture=next;sync();emit()}
  function setTraces(value){const next=!!value;if(!!state.traces===next)return;checkpoint();state.traces=next;sync();emit()}
  sync();return{state,refresh(){sync()},setTexture,setTraces,updateCount(graph){const count=panel.querySelector('.hero-graph-count');if(count)count.textContent=`${graph.active.length} squares · ${graph.edges.length} lines`},pause:panel.querySelector('.studio-pause')};
}

export async function loadStudioSettings(id){
  try{const data=await (await fetch(new URL('./studio-settings.json',import.meta.url),{cache:'no-store'})).json();return data[id]?.state?data[id]:null}catch{return null}
}
